using UnityEngine;

namespace AlienInvaders.Views
{
    /// <summary>
    /// Every sound of the game in one asset, so swapping a sound never touches code: views ask for "a player shot"
    /// or "an explosion" and get one of the clips assigned here (a random one when there are several, so repeated
    /// sounds do not feel mechanical). Any slot left empty falls back to the sound generated by PlaceholderSounds.
    /// </summary>
    [CreateAssetMenu(fileName = "GameSounds", menuName = "Alien Invaders/Game Sounds")]
    public class GameSounds : ScriptableObject
    {
        [Header("Weapon")]
        [SerializeField] private AudioClip[] _playerShots;
        [SerializeField] private AudioClip _overheat;

        [Header("Power ups")]
        [SerializeField] private AudioClip _powerUpAppear;
        [SerializeField] private AudioClip _powerUpHit;
        [SerializeField] private AudioClip _powerUp;
        [SerializeField] private AudioClip _superHum;

        [Header("Ships")]
        [SerializeField] private AudioClip _shipEngine;
        [SerializeField] private AudioClip _charge;
        [SerializeField] private AudioClip[] _enemyShots;
        [SerializeField] private AudioClip[] _explosions;

        [Header("World")]
        [SerializeField] private AudioClip _portalHum;
        [SerializeField] private AudioClip _towerRumble;
        [SerializeField] private AudioClip _alarm;
        [SerializeField] private AudioClip _wind;

        [Header("Elevator")]
        [SerializeField] private AudioClip _elevatorRide;
        [SerializeField] private AudioClip _doorOpen;
        [SerializeField] private AudioClip _doorClose;

        [Header("Titles")]
        [SerializeField] private AudioClip _beep;
        [SerializeField] private AudioClip _go;

        public AudioClip PlayerShot => Pick(_playerShots, PlaceholderSounds.PlayerShot);
        public AudioClip Overheat => Or(_overheat, PlaceholderSounds.Overheat);
        public AudioClip PowerUpAppear => Or(_powerUpAppear, PlaceholderSounds.PowerUpAppear);
        public AudioClip PowerUpHit => Or(_powerUpHit, PlaceholderSounds.PowerUpHit);
        public AudioClip PowerUp => Or(_powerUp, PlaceholderSounds.PowerUp);

        /// <summary>Loop: electric hum of the super weapon while a power up lasts.</summary>
        public AudioClip SuperHum => Or(_superHum, PlaceholderSounds.SuperHum);
        public AudioClip ShipEngine => Or(_shipEngine, PlaceholderSounds.Engine);
        public AudioClip Charge => Or(_charge, PlaceholderSounds.Charge);
        public AudioClip EnemyShot => Pick(_enemyShots, PlaceholderSounds.EnemyShot);
        public AudioClip Explosion => Pick(_explosions, PlaceholderSounds.Explosion);
        public AudioClip PortalHum => Or(_portalHum, PlaceholderSounds.PortalHum);
        public AudioClip TowerRumble => Or(_towerRumble, PlaceholderSounds.Rumble);
        public AudioClip Alarm => Or(_alarm, PlaceholderSounds.Alarm);

        /// <summary>Wind at the top of the tower (no generated fallback: silence is better than fake wind).</summary>
        public AudioClip Wind => _wind;

        /// <summary>Hum of the elevator machinery while it moves (no generated fallback).</summary>
        public AudioClip ElevatorRide => _elevatorRide;

        public AudioClip DoorOpen => _doorOpen;
        public AudioClip DoorClose => _doorClose;
        public AudioClip Beep => Or(_beep, PlaceholderSounds.Beep);
        public AudioClip Go => Or(_go, PlaceholderSounds.Go);

        private static AudioClip Pick(AudioClip[] clips, AudioClip fallback)
        {
            return clips != null && clips.Length > 0 ? clips[Random.Range(0, clips.Length)] : fallback;
        }

        private static AudioClip Or(AudioClip clip, AudioClip fallback)
        {
            return clip != null ? clip : fallback;
        }
    }
}
